window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[64]={"id":"064","numero":64,"titre":"Trouble bipolaire (ado & adulte)","objectifs":[{"id":"64-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un épisode maniaque","contenu":"<p>Le <span class=\"kw-def\">syndrome maniaque</span> se définit par une <strong>augmentation pathologique de l'humeur et de l'énergie ou de l'activité</strong>, <span class=\"kw-clinique\">persistante dans le temps</span> (<span class=\"kw-chiffre\">≥ 1 semaine</span>). L'installation peut être <span class=\"kw-clinique\">brutale ou progressive</span>, avec ou sans facteur déclenchant.</p>\n      <p>C'est une <span class=\"kw-alerte\">urgence médicale</span> — diagnostique et thérapeutique — qui nécessite généralement une <span class=\"kw-alerte\">hospitalisation</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">altérations du sommeil</span> (<span class=\"kw-ttt\">réduction</span> du temps de sommeil, insomnie sans fatigue) sont souvent <span class=\"kw-clinique\">prodromiques</span> de l'épisode. Le tableau se décline en <strong>3 composantes</strong> : psychoaffective, psychomotrice et physiologique.</p>\n      <table >\n        <thead><tr><th>Critère DSM-5</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A — Humeur</strong></td><td>Période <span class=\"kw-clinique\">nettement délimitée</span> d'humeur <span class=\"kw-clinique\">élevée, expansive ou irritable</span> de façon anormale, avec augmentation anormale de l'<span class=\"kw-clinique\">énergie ou de l'activité</span> orientée vers un but, presque tous <span class=\"kw-clinique\">les</span> jours, pendant <span class=\"kw-chiffre\">≥ 1 semaine</span> — <strong>ou toute autre durée si une <span class=\"kw-alerte\">hospitalisation</span> est nécessaire</strong></td></tr>\n          <tr><td><strong>B — Symptômes</strong></td><td><span class=\"kw-chiffre\">≥ 3/7</span> symptômes (<span class=\"kw-chiffre\">4</span> si l'humeur est seulement irritable) : augmentation de l'estime de soi / idées de grandeur ; <span class=\"kw-ttt\">réduction</span> du besoin de sommeil ; communicabilité accrue ; fuite des idées ; distractibilité ; augmentation de l'activité orientée vers un but ou agitation psychomotrice ; engagement excessif dans des activités à risque</td></tr>\n          <tr><td><strong>C — Retentissement</strong></td><td>Altération marquée du <span class=\"kw-clinique\">fonctionnement</span> professionnel ou social ; <strong>ou</strong> nécessité d'une <span class=\"kw-alerte\">hospitalisation</span> ; <strong>ou</strong> présence de <span class=\"kw-alerte\">caractéristiques psychotiques</span></td></tr>\n          <tr><td><strong>D — Exclusion</strong></td><td>Non imputable aux effets physiologiques d'une <span class=\"kw-clinique\">substance</span> ou d'une autre <span class=\"kw-clinique\">affection médicale générale</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Nuance sur le critère D.</strong> Un épisode maniaque complet apparu au cours d'un traitement <span class=\"kw-ttt\">antidépresseur</span> (ou électroconvulsivothérapie) mais qui <strong>persiste au-delà de l'effet physiologique</strong> de ce traitement doit être considéré comme un <span class=\"kw-def\">épisode maniaque</span> — et conduit donc au diagnostic de <span class=\"kw-def\">trouble bipolaire</span>.</div>","frequence":2},{"id":"64-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un épisode hypomaniaque","contenu":"<p>Comme dans le syndrome maniaque, le sujet présente une <strong><span class=\"kw-alerte\">rupture</span> totale avec l'état antérieur</strong> (souvent constatée par l'entourage) et <span class=\"kw-clinique\">les</span> <strong>mêmes manifestations</strong> que le syndrome maniaque — mais en <span class=\"kw-clinique\">moins intense</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Épisode maniaque</th><th>Épisode hypomaniaque</th></tr></thead>\n        <tbody>\n          <tr><td>Durée</td><td><span class=\"kw-chiffre\">≥ 1 semaine</span></td><td><span class=\"kw-chiffre\">≥ 4 jours consécutifs</span></td></tr>\n          <tr><td>Intensité / retentissement</td><td>Symptomatologie et retentissement fonctionnel marqués</td><td>Symptomatologie et retentissement fonctionnel moins importants</td></tr>\n          <tr><td><span class=\"kw-alerte\">Hospitalisation</span></td><td><span class=\"kw-alerte\">Généralement nécessaire</span></td><td>Non nécessaire, mais <span class=\"kw-clinique\">PEC rapide</span> requise</td></tr>\n          <tr><td>Caractéristiques psychotiques</td><td>Possibles</td><td><span class=\"kw-alerte\">Absentes</span> — leur présence reclasse l'épisode en maniaque</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Dès qu'il existe des <span class=\"kw-alerte\">caractéristiques psychotiques</span>, ou que la sévérité impose une <span class=\"kw-alerte\">hospitalisation</span> ou entraîne une altération marquée du fonctionnement, l'épisode est <strong>par définition maniaque</strong> — jamais hypomaniaque.</div>","frequence":0},{"id":"64-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un épisode dépressif bipolaire","contenu":"<p>Le <span class=\"kw-def\">syndrome dépressif</span> se caractérise par la persistance dans le temps (<span class=\"kw-chiffre\">≥ 15 jours</span>) d'une <strong>tristesse pathologique de l'humeur</strong> et d'une <strong>baisse d'énergie</strong>.</p>\n      <p>Le diagnostic d'<span class=\"kw-def\">épisode dépressif caractérisé</span> (EDC) repose sur 4 conditions : un syndrome dépressif ; une <span class=\"kw-clinique\">évolution</span> depuis <span class=\"kw-chiffre\">≥ 15 jours</span> ; une altération marquée du <span class=\"kw-clinique\">fonctionnement</span> professionnel, social ou relationnel ; l'absence de <span class=\"kw-def\">diagnostic différentiel</span>. L'EDC est dit « <strong>bipolaire</strong> » lorsqu'il survient dans le cadre d'un <span class=\"kw-def\">trouble bipolaire</span> — ses <span class=\"kw-def\">critères diagnostiques</span> sont identiques à ceux de l'EDC unipolaire.</p>\n      <table >\n        <thead><tr><th>Critère DSM-5</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A — Symptômes</strong></td><td>Présence de <span class=\"kw-chiffre\">≥ 5/9</span> symptômes pendant une même période de <span class=\"kw-chiffre\">2 semaines</span>, représentant un <span class=\"kw-clinique\">changement par rapport à l'état antérieur</span> ; avec <span class=\"kw-chiffre\">≥ 1</span> symptôme qui est soit une <span class=\"kw-clinique\">humeur dépressive</span>, soit une <span class=\"kw-clinique\">perte d'intérêt ou de plaisir</span></td></tr>\n          <tr><td><strong>B — Retentissement</strong></td><td><span class=\"kw-clinique\">Détresse cliniquement significative</span> ou altération du fonctionnement social, professionnel ou dans d'autres domaines importants</td></tr>\n          <tr><td><strong>C — Exclusion organique</strong></td><td>Non imputable aux effets physiologiques d'une <span class=\"kw-clinique\">substance</span> ou d'une autre <span class=\"kw-clinique\">affection médicale générale</span></td></tr>\n          <tr><td><strong>D — Exclusion psychotique</strong></td><td>Ne répond pas aux critères d'un <span class=\"kw-etio\">trouble schizo-affectif</span> et ne se superpose pas à une <span class=\"kw-etio\">schizophrénie</span> ou à un autre trouble psychotique</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>9 symptômes du critère A</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Humeur dépressive</span> présente quasiment toute la journée, presque tous <span class=\"kw-clinique\">les</span> jours</li>\n        <li><span class=\"kw-clinique\">Diminution marquée de l'intérêt ou du plaisir</span> pour presque toutes <span class=\"kw-clinique\">les</span> activités</li>\n        <li><span class=\"kw-clinique\">Perte ou gain de poids</span> significatif, ou modification de l'appétit</li>\n        <li><span class=\"kw-clinique\">Insomnie ou hypersomnie</span> presque tous <span class=\"kw-clinique\">les</span> jours</li>\n        <li><span class=\"kw-clinique\">Agitation ou ralentissement psychomoteur</span></li>\n        <li><span class=\"kw-clinique\">Fatigue ou perte d'énergie</span></li>\n        <li><span class=\"kw-clinique\">Sentiment de dévalorisation ou de culpabilité</span> excessive</li>\n        <li><span class=\"kw-clinique\">Diminution de l'aptitude à penser / se concentrer</span>, ou indécision</li>\n        <li><span class=\"kw-alerte\">Pensées de mort récurrentes, idées suicidaires</span> (avec ou sans plan)</li>\n      </ul>","frequence":1},{"id":"64-4","rang":"B","rubrique":"Définition","titre":"Connaître la définition des troubles bipolaires I et II","contenu":"<p>Le <span class=\"kw-def\">trouble bipolaire</span> est un trouble psychiatrique <strong>sévère, chronique et fréquent</strong>. Il se caractérise par des <strong>changements pathologiques de l'humeur, de l'activité et de l'énergie</strong>, qui peuvent être augmentées (la <span class=\"kw-def\">manie</span>) ou diminuées (la <span class=\"kw-def\">dépression</span>). Selon l'<span class=\"kw-def\">OMS</span>, il fait partie des <span class=\"kw-chiffre\">10 maladies les plus invalidantes et coûteuses</span> au plan mondial.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Définition</th><th>Notes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type I</strong></td><td>Survenue d'<span class=\"kw-chiffre\">un ou plusieurs épisode(s) maniaque(s)</span></td><td>Le diagnostic peut être posé <strong>même en l'absence d'<span class=\"kw-def\">épisode dépressif caractérisé</span></strong> ; il peut aussi y avoir des épisodes hypomaniaques</td></tr>\n          <tr><td><strong>Type II</strong></td><td>Survenue d'<span class=\"kw-chiffre\">≥ 1 épisode hypomaniaque</span> <strong>et</strong> d'<span class=\"kw-chiffre\">≥ 1 épisode dépressif caractérisé</span></td><td>Il ne doit <span class=\"kw-alerte\">jamais y avoir eu d'épisode maniaque</span> — sinon le trouble est de type I</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Dans <span class=\"kw-clinique\">les</span> 2 types, le trouble ne doit pas être expliqué par un <span class=\"kw-etio\">diagnostic différentiel</span> non psychiatrique, <span class=\"kw-etio\">iatrogène</span>, ou par une intoxication à une substance psychoactive.</div>","frequence":1},{"id":"64-5","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span> des formes typiques (sous-types I ou II)</td><td><strong>Population générale :</strong> <span class=\"kw-chiffre\">1-4 %</span><br><strong>Enfant</strong> (rare) : <span class=\"kw-chiffre\">0,1 %</span><br><strong>Adolescent</strong> (plus fréquent) : <span class=\"kw-chiffre\">&gt; 1 %</span></td></tr>\n          <tr><td>Âge de début</td><td>Habituellement entre <span class=\"kw-chiffre\">15-25 ans</span> (juste après la puberté) ; début avant <span class=\"kw-chiffre\">21 ans</span> dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas</td></tr>\n          <tr><td>Sex-ratio</td><td><strong>Sous-type I :</strong> sex-ratio à <span class=\"kw-chiffre\">1</span><br><strong>Sous-type II :</strong> prédominance <span class=\"kw-clinique\">féminine</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"64-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution, la morbi-mortalité psychiatrique et non psychiatrique","contenu":"<p><strong><span class=\"kw-def\">Facteurs de risque</span>.</strong> L'<span class=\"kw-etio\">héritabilité</span> de la maladie est de <span class=\"kw-chiffre\">60-70 %</span>. <span class=\"kw-clinique\">Les</span> facteurs de risque environnementaux comprennent les <span class=\"kw-etio\">traumatismes dans l'enfance</span> (sexuels, affectifs, émotionnels) et les <span class=\"kw-etio\">stress environnementaux plus tardifs</span> (aigus ou répétés).</p>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> et <span class=\"kw-def\">pronostic</span>.</strong> C'est une <span class=\"kw-def\">maladie chronique</span> : <span class=\"kw-clinique\">les</span> récidives sont la règle, quelle que soit la polarité.</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">70-80 %</span> des patients traités présentent une <span class=\"kw-clinique\">récidive thymique</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> suivant un épisode caractérisé</li>\n        <li><span class=\"kw-chiffre\">&gt; 90 %</span> des personnes ayant présenté un épisode maniaque auront d'autres épisodes de l'humeur</li>\n        <li><span class=\"kw-alerte\">10-20 années de vie perdues</span> du fait d'une <span class=\"kw-def\">mortalité</span> précoce (principalement cardiovasculaire et par suicide)</li>\n        <li>Le <span class=\"kw-def\">pronostic</span> dépend en partie d'une <span class=\"kw-clinique\">prise en charge précoce et adaptée</span> — une <span class=\"kw-clinique\">rémission</span> symptomatique et fonctionnelle est possible</li>\n      </ul>\n      <p><strong>Complications et <span class=\"kw-def\">comorbidités</span>.</strong></p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Évolutives</td><td><span class=\"kw-clinique\">Cycles rapides</span> (<span class=\"kw-chiffre\">≥ 4 épisodes</span> de l'humeur sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12 derniers mois</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Comorbidités</span> psychiatriques</td><td>Troubles addictifs ; troubles anxieux ; troubles du sommeil et des rythmes</td></tr>\n          <tr><td><span class=\"kw-def\">Comorbidités</span> non psychiatriques</td><td>Maladies cardiovasculaires ; <span class=\"kw-def\">syndrome métabolique</span> ; <span class=\"kw-etio\">SAHOS</span> ; pathologies endocriniennes, tumorales, neurodégénératives</td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> et retentissement</td><td><span class=\"kw-alerte\">Suicide : 15 % des patients</span> décèdent par suicide ; <span class=\"kw-clinique\">actes médico-légaux</span> ; <span class=\"kw-clinique\">désinsertion</span> familiale (<span class=\"kw-chiffre\">3×</span> plus de divorces), professionnelle et sociale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> pronostique.</strong> Le <span class=\"kw-alerte\">risque suicidaire</span> domine la morbi-<span class=\"kw-def\">mortalité</span> psychiatrique : <span class=\"kw-chiffre\">15 %</span> des patients souffrant d'un <span class=\"kw-def\">trouble bipolaire</span> décèdent par suicide.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p>","frequence":1},{"id":"64-7","rang":"B","rubrique":"Étiologie","titre":"Savoir que l’étiologie des troubles bipolaires est multifactorielle","contenu":"<p>Le <span class=\"kw-def\">trouble bipolaire</span> est d'origine <span class=\"kw-def\">multifactorielle</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Héritabilité</span></strong> de la maladie (part d'expression clinique liée aux <span class=\"kw-etio\">gènes</span>) estimée à <span class=\"kw-chiffre\">60-70 %</span></li>\n        <li><strong><span class=\"kw-def\">Facteurs de risque</span> environnementaux</strong> : <span class=\"kw-etio\">traumatismes dans l'enfance</span> (sexuels, affectifs ou émotionnels) ; <span class=\"kw-etio\">stress environnementaux plus tardifs</span>, aigus ou répétés</li>\n        <li><strong>Hypothèses <span class=\"kw-def\">neurodéveloppementales</span></strong> également proposées</li>\n      </ul>","frequence":0},{"id":"64-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","contenu":"<p>Le sujet en <span class=\"kw-def\">syndrome maniaque</span> est comparable à une « pile électrique » chez qui tout va trop vite, avec une <span class=\"kw-alerte\">faible conscience du caractère pathologique</span> de ses symptômes. La sémiologie se décline en <strong>3 composantes</strong>.</p>\n      <table >\n        <thead><tr><th>Perturbations psychoaffectives</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Humeur</td><td>Humeur <span class=\"kw-clinique\">élevée, expansive, exaltée, euphorique</span> ; peut s'associer ou être remplacée par une <span class=\"kw-clinique\">irritabilité</span> (le vécu n'est pas toujours agréable)</td></tr>\n          <tr><td>Émotions</td><td><span class=\"kw-clinique\">Labilité émotionnelle</span> ; <span class=\"kw-clinique\">hyperréactivité / hyperesthésie</span> ; <span class=\"kw-clinique\">hypersyntonie</span> (adhésion très rapide à l'ambiance affective)</td></tr>\n          <tr><td>Contenu de la pensée</td><td>Augmentation de l'<span class=\"kw-clinique\">estime de soi</span> ; <span class=\"kw-clinique\">idées de grandeur, de toute-puissance, mégalomaniaques</span> ; <span class=\"kw-alerte\">absence de conscience du trouble</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Perturbations psychomotrices</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Cours de la pensée</td><td><span class=\"kw-clinique\">Tachypsychie</span> ; <span class=\"kw-clinique\">pensée diffluente / fuite des idées</span> ; <span class=\"kw-clinique\">coq-à-l'âne</span> ; jeux de mots, associations par assonances</td></tr>\n          <tr><td>Cognition</td><td><span class=\"kw-clinique\">Hypervigilance</span> ; <span class=\"kw-clinique\">distractibilité</span> ; altérations de l'attention et de la concentration</td></tr>\n          <tr><td>Moteur et comportement</td><td>Agitation, <span class=\"kw-clinique\">hyperactivité souvent stérile</span> ; augmentation de l'énergie et des activités à but dirigé ; <span class=\"kw-clinique\">logorrhée</span> ; <span class=\"kw-clinique\">tachyphémie</span> ; <span class=\"kw-clinique\">hypermimie</span> ; <span class=\"kw-clinique\">désinhibition</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Perturbations physiologiques</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Sommeil et rythmes circadiens</td><td><span class=\"kw-clinique\">Insomnie</span> ; <span class=\"kw-clinique\">réduction du temps de sommeil sans sensation de fatigue</span></td></tr>\n          <tr><td>Conduites alimentaires</td><td><span class=\"kw-clinique\">Anorexie ou hyperphagie</span> ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-clinique\">déshydratation</span> possible</td></tr>\n          <tr><td>Sexualité</td><td>Augmentation du désir et de l'excitation ; <span class=\"kw-clinique\">hypersexualité</span> (comportements sexuels impulsifs et à risque)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Symptômes psychotiques associés.</strong> Ils peuvent être au 1er plan et égarer le diagnostic : <span class=\"kw-clinique\">hallucinations</span> dans <span class=\"kw-chiffre\">40-50 %</span> des syndromes maniaques ; <span class=\"kw-clinique\">idées délirantes</span> classiquement « <span class=\"kw-clinique\">congruentes à l'humeur</span> » (mégalomanie, thème mystique), de mécanisme le plus souvent imaginatif et interprétatif.</div>\n      <p><strong>Syndrome hypomaniaque.</strong> Mêmes manifestations que le syndrome maniaque mais en <span class=\"kw-clinique\">moins intense</span> ; durée <span class=\"kw-chiffre\">≥ 4 jours consécutifs</span> ; retentissement fonctionnel moindre ; pas d'<span class=\"kw-alerte\">hospitalisation</span> nécessaire mais PEC rapide requise.</p>\n      <table >\n        <thead><tr><th>Intensité</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Léger</strong></td><td>Symptômes juste suffisants au diagnostic ; peu de perturbations sociales ou professionnelles</td></tr>\n          <tr><td><strong>Moyen</strong></td><td>Plus de symptômes que nécessaire ; perturbations modérées sociales ou professionnelles</td></tr>\n          <tr><td><strong>Sévère</strong></td><td>Quasiment tous <span class=\"kw-clinique\">les</span> symptômes ; perturbations nettes sociales ou professionnelles</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Chez l'enfant et l'adolescent.</strong> Le diagnostic est <span class=\"kw-alerte\">difficile</span> : au 1er plan, on s'appuie sur l'<span class=\"kw-clinique\">irritabilité</span>, voire l'<span class=\"kw-clinique\">agressivité</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 351 — Agitation et délire aigu</em></p>","frequence":8},{"id":"64-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie du syndrome dépressif","contenu":"<p>Le <span class=\"kw-def\">syndrome dépressif</span> (persistance <span class=\"kw-chiffre\">≥ 15 jours</span> d'une tristesse pathologique de l'humeur et d'une baisse d'énergie) se décline en <strong>3 composantes</strong>.</p>\n      <table >\n        <thead><tr><th>Perturbations psychoaffectives</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Humeur</td><td>Humeur <span class=\"kw-clinique\">dépressive / triste</span>, sentiment pénible et envahissant, quasi constante ; <span class=\"kw-clinique\">prédomine le matin dès le réveil</span>, avec tendance à s'améliorer au cours de la journée</td></tr>\n          <tr><td>Émotions</td><td><span class=\"kw-clinique\">Anhédonie</span> (perte du plaisir) ; <span class=\"kw-clinique\">anesthésie affective</span> (émoussement émotionnel) ; <span class=\"kw-clinique\">anxiété</span> ; <span class=\"kw-clinique\">irritabilité</span>, surtout chez l'adolescent</td></tr>\n          <tr><td>Contenu de la pensée</td><td>Idées de <span class=\"kw-clinique\">culpabilité / auto-accusation</span> ; idées de <span class=\"kw-clinique\">dévalorisation</span> ; idées d'<span class=\"kw-clinique\">incurabilité</span></td></tr>\n          <tr><td>Pensées de mort</td><td>Pensées centrées sur la mort ; <span class=\"kw-alerte\">idées suicidaires</span> avec ou sans plan précis</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Perturbations psychomotrices</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Cours de la pensée</td><td><span class=\"kw-clinique\">Bradypsychie</span> (ralentissement des idées) ; <span class=\"kw-clinique\">ruminations</span> ; <span class=\"kw-clinique\">monoïdéisme</span></td></tr>\n          <tr><td>Cognition</td><td>Altérations de la concentration, de la mémoire et de l'attention ; <span class=\"kw-clinique\">indécision</span></td></tr>\n          <tr><td>Ralentissement moteur</td><td><span class=\"kw-clinique\">Bradykinésie</span> ; <span class=\"kw-clinique\">hypomimie</span> voire amimie ; <span class=\"kw-clinique\">bradyphémie</span> ; voix monocorde (<span class=\"kw-clinique\">aprosodie</span>) ; <span class=\"kw-clinique\">clinophilie</span> ; <span class=\"kw-clinique\">incurie</span> ; <span class=\"kw-clinique\">aboulie</span></td></tr>\n          <tr><td>Agitation psychomotrice</td><td>Déambulations permanentes, liées à un état de tension interne et d'anxiété accrue (peut alterner avec le ralentissement)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Perturbations physiologiques</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Sommeil</td><td><span class=\"kw-clinique\">Insomnie</span> (réveils nocturnes, réveils précoces, difficultés d'endormissement) ; somnolence possible</td></tr>\n          <tr><td>Énergie</td><td><span class=\"kw-clinique\">Fatigue</span> et <span class=\"kw-clinique\">asthénie</span> — signe d'appel fréquent, non spécifique</td></tr>\n          <tr><td>Conduites alimentaires</td><td><span class=\"kw-clinique\">Anorexie</span> (le plus fréquent) ou augmentation de l'appétit ; variations de poids</td></tr>\n          <tr><td>Sexualité</td><td><span class=\"kw-clinique\">Hyposexualité</span> : diminution du désir et de l'excitation sexuelle</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Population</th><th>Spécificités sémiologiques</th></tr></thead>\n        <tbody>\n          <tr><td>Enfant, adolescent</td><td>L'humeur peut se manifester par des <span class=\"kw-clinique\">crises de colère</span> ou de l'<span class=\"kw-clinique\">irritabilité</span> plutôt que de la tristesse ; <span class=\"kw-clinique\">altération du rendement scolaire</span> ; plus le 1er épisode est <span class=\"kw-alerte\">précoce</span>, plus le risque de récidive et le risque suicidaire est élevé</td></tr>\n          <tr><td>Personne âgée</td><td>Plaintes d'allure non psychiatrique (en particulier <span class=\"kw-clinique\">algiques</span>), plaintes <span class=\"kw-clinique\">mnésiques</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 144 — Deuil</em></p>","frequence":1},{"id":"64-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques évocatrices d’une dépression bipolaire","contenu":"<p>Il est particulièrement délicat de distinguer un syndrome dépressif émaillant l'<span class=\"kw-clinique\">évolution</span> d'un <span class=\"kw-def\">trouble bipolaire</span> d'un <span class=\"kw-def\">épisode dépressif unipolaire</span>. Certaines caractéristiques doivent faire <strong>évoquer un <span class=\"kw-def\">trouble bipolaire</span></strong>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Caractéristiques évocatrices</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-etio\">ATCD familial de trouble de l'humeur</span> ; <span class=\"kw-def\">épisode dépressif caractérisé</span> avant <span class=\"kw-chiffre\">25 ans</span></td></tr>\n          <tr><td><strong>Contexte</strong></td><td>EDC en <span class=\"kw-clinique\">post-partum</span> ; ATCD d'épisodes dépressifs caractérisés multiples (<span class=\"kw-chiffre\">≥ 3</span>)</td></tr>\n          <tr><td><strong>Lié à l'épisode</strong></td><td>EDC de <span class=\"kw-clinique\">début brutal</span> ; caractéristiques cliniques <span class=\"kw-clinique\">mélancolique</span> et <span class=\"kw-clinique\">saisonnier</span></td></tr>\n          <tr><td><strong>Réponse au traitement</strong></td><td>Réponse inadéquate à un antidépresseur : <span class=\"kw-alerte\">non-réponse voire aggravation</span> des symptômes ; apparition d'une <span class=\"kw-alerte\">agitation</span> ; apparition d'une <span class=\"kw-alerte\">hypomanie</span>, même brève</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Enjeu thérapeutique.</strong> Ces caractéristiques doivent faire rechercher activement un <span class=\"kw-def\">trouble bipolaire</span> avant de conclure à une <span class=\"kw-def\">dépression</span> unipolaire : un <span class=\"kw-ttt\">antidépresseur</span> prescrit seul peut induire un <span class=\"kw-alerte\">virage maniaque</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 69 — Trouble psy <span class=\"kw-ci\">grossesse</span> - postpartum</em></p>","frequence":5},{"id":"64-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<p>Comme pour tout trouble psychiatrique, une <span class=\"kw-etio\">étiologie non psychiatrique</span> doit être éliminée à l'aide d'un bilan clinique et paraclinique.</p>\n      <table >\n        <thead><tr><th>Diagnostics différentiels non psychiatriques</th><th>Diagnostics différentiels psychiatriques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Substances psychoactives :</strong> <span class=\"kw-def\">diagnostic différentiel</span> <span class=\"kw-alerte\">le plus fréquent</span><br>\n              <strong>Neurologiques :</strong> tumeur cérébrale ; SEP ; <span class=\"kw-etio\">AVC</span> ; pathologie neurodégénérative (surtout si épisode après <span class=\"kw-chiffre\">40 ans</span>) ; <span class=\"kw-etio\">épilepsie</span> focale (rare)<br>\n              <strong>Endocriniennes :</strong> dysthyroïdies ; maladie de Cushing<br>\n              <strong>Métaboliques :</strong> hypoglycémie ; troubles ioniques ; <span class=\"kw-etio\">maladie de Wilson</span><br>\n              <strong>Iatrogéniques :</strong> <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-ttt\">antidépresseurs</span> ; <span class=\"kw-ttt\">interféron α</span> ; <span class=\"kw-ttt\">β-bloquants</span> ; <span class=\"kw-ttt\">L-DOPA</span>\n            </td>\n            <td>\n              Autres troubles de l'humeur<br>\n              Trouble de la personnalité<br>\n              TDAH<br>\n              <span class=\"kw-etio\">Schizophrénie</span><br>\n              Troubles anxieux<br>\n              Trouble obsessionnel-compulsif (TOC)<br>\n              Trouble délirant persistant<br>\n              Troubles addictifs\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Bilan d'élimination</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Bilan sanguin</td><td><span class=\"kw-bio\">Glycémie</span> ; <span class=\"kw-bio\">ionogramme, calcémie</span> ; <span class=\"kw-bio\">bilan rénal</span> (<span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatininémie</span>) ; <span class=\"kw-bio\">NFS-plaquettes, CRP</span> ; <span class=\"kw-bio\">TSHus</span> ; <span class=\"kw-bio\">bilan hépatique</span></td></tr>\n          <tr><td>Bilan urinaire</td><td><span class=\"kw-bio\">Toxiques urinaires</span> : cannabis, cocaïne, <span class=\"kw-ttt\">opiacés</span>, amphétamines</td></tr>\n          <tr><td>Autres</td><td><strong>Imagerie cérébrale :</strong> au mieux une <span class=\"kw-imagerie\">IRM</span> si <span class=\"kw-clinique\">premier épisode</span> — en <span class=\"kw-alerte\">urgence</span> si signe d'appel neurologique ou manifestations atypiques<br><strong><span class=\"kw-imagerie\">EEG</span> :</strong> si 1er épisode ou signes d'appel neurologique<br><strong><span class=\"kw-bio\">ECG</span> :</strong> <span class=\"kw-ci\">bilan pré-thérapeutique</span> des antipsychotiques et du <span class=\"kw-ttt\">lithium</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 65 — Trouble délirant persistant · 66 — Trouble dépressif · 66 — Trouble de la personnalité</em></p>","frequence":3},{"id":"64-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p><strong>Indications d'<span class=\"kw-alerte\">hospitalisation</span> en psychiatrie.</strong></p>\n      <table >\n        <thead><tr><th>Indication</th><th>Précision</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Épisode maniaque</span></td><td><span class=\"kw-alerte\">Urgence</span> médicale : requiert dans la majorité des situations une <span class=\"kw-alerte\">hospitalisation</span> en urgence, en psychiatrie</td></tr>\n          <tr><td><span class=\"kw-def\">Épisode dépressif caractérisé</span></td><td>Si <span class=\"kw-clinique\">sévère</span>, ou en présence de <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> (caractéristique mélancolique, psychotique, mixte, catatonique)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Risque suicidaire</span></td><td>Élevé, ou risque de mise en danger</td></tr>\n          <tr><td>Perturbations importantes du comportement</td><td>Conséquences potentiellement délétères pour le patient, l'entourage, <span class=\"kw-clinique\">les</span> soignants</td></tr>\n          <tr><td><span class=\"kw-alerte\">Risque hétéro-agressif</span></td><td>Ou complications médico-légales</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Phase de traitement</th><th>Durée</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr><td>Traitement d'attaque</td><td><span class=\"kw-chiffre\">6-8 semaines</span></td><td><span class=\"kw-clinique\">Rémission</span> symptomatique</td></tr>\n          <tr><td>Traitement de consolidation</td><td><span class=\"kw-chiffre\">4-6 mois</span></td><td>Prévention de la rechute, <span class=\"kw-clinique\">rémission</span> fonctionnelle</td></tr>\n          <tr><td>Traitement prophylactique</td><td><span class=\"kw-chiffre\">Au long cours</span></td><td>Prévention des récurrences</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Psychothérapie.</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Éducation thérapeutique</span> — excellente efficacité : compréhension du trouble, repérage des signes précurseurs de rechute, régularité des rythmes de vie</li>\n        <li><span class=\"kw-clinique\">Psychothérapie de soutien</span> — toujours indiquée, s'<strong>associe au traitement <span class=\"kw-etio\">médicamenteux</span> sans s'y substituer</strong></li>\n        <li><span class=\"kw-clinique\">TCC et thérapies interpersonnelles</span> — niveaux de preuve <span class=\"kw-clinique\">les</span> plus élevés</li>\n        <li><span class=\"kw-clinique\">Remédiation cognitive</span> — pour <span class=\"kw-clinique\">les</span> troubles cognitifs, présents chez <span class=\"kw-chiffre\">1/3</span> des patients ; bilan neuropsychologique préalable</li>\n      </ul>\n      <p><strong>Prise en charge sociale et juridique.</strong> <span class=\"kw-clinique\">ALD 30 à 100 %</span> avec exonération du ticket modérateur ; réadaptation psychosociale si handicap.</p>\n      <div class=\"callout callout-warn\"><strong>Protection juridique.</strong> En cas de dépenses ou d'achats excessifs : <span class=\"kw-clinique\">sauvegarde de justice</span>. <span class=\"kw-alerte\">Pas de curatelle ni de tutelle en urgence.</span></div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement · 351 — Agitation et délire aigu · 353 — Risque et conduite suicidaire</em></p>","frequence":2},{"id":"64-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications du traitement pharmacologique des épisodes aigus","contenu":"<p>Tout épisode aigu comporte un <strong>traitement symptomatique</strong> : prise en charge de l'agitation et du risque hétéro-agressif, du <span class=\"kw-alerte\">risque suicidaire</span>, réhydratation et correction des troubles hydro-électrolytiques, prise en charge des perturbations du <span class=\"kw-clinique\">sommeil</span>, prévention des conduites à risque (notamment rapports sexuels non protégés).</p>\n      <table >\n        <thead><tr><th>Épisode</th><th>Traitement pharmacologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Épisode maniaque</strong></td>\n            <td>\n              <strong>1ʳᵉ intention :</strong> thymorégulateur <span class=\"kw-ttt\">lithium</span>, et/ou antipsychotique de 2ᵉ génération [QORA] — <span class=\"kw-ttt\">quétiapine</span>, <span class=\"kw-ttt\">olanzapine</span>, <span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">aripiprazole</span><br>\n              <strong>Si CI ou inefficacité du <span class=\"kw-ttt\">lithium</span> :</strong> <span class=\"kw-ttt\">carbamazépine</span>, <span class=\"kw-ttt\">valproate</span><br>\n              <strong>Épisode sévère :</strong> association thymorégulateur + antipsychotique possible<br>\n              <strong>Mesure clé :</strong> arrêt de l'antidépresseur s'il est présent\n            </td>\n          </tr>\n          <tr>\n            <td><strong>EDC du <span class=\"kw-def\">trouble bipolaire</span></strong></td>\n            <td>\n              <strong>1ʳᵉ ligne (monothérapie) :</strong> <span class=\"kw-ttt\">lithium</span>, ou <span class=\"kw-ttt\">lamotrigine</span>, ou <span class=\"kw-ttt\">quétiapine</span><br>\n              <strong>Évaluation :</strong> la réponse nécessite <span class=\"kw-chiffre\">≥ 2 semaines</span> de traitement à dose efficace<br>\n              <strong>2ᵉ ligne :</strong> si un thymorégulateur (<span class=\"kw-ttt\">lithium</span> ou <span class=\"kw-ttt\">valproate</span>) est déjà en place à posologie efficace → ajout possible d'un <span class=\"kw-ttt\">antidépresseur ISRS</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Antidépresseurs — prudence.</strong> Chez le patient bipolaire, <span class=\"kw-clinique\">les</span> antidépresseurs exposent à un <span class=\"kw-alerte\">virage maniaque</span> (effet aigu) et, au long cours, favorisent les rechutes et l'<span class=\"kw-alerte\">accélération des cycles</span>. Un antidépresseur ne doit <strong>jamais être prescrit seul</strong> — toujours associé à un thymorégulateur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":2},{"id":"64-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement pharmacologique au long cours","contenu":"<p>La prise en charge au long cours suit <strong>3 phases</strong>, prolongeant le traitement de l'épisode aigu.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Durée</th><th>Objectif</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Traitement d'attaque</td><td><span class=\"kw-chiffre\">6-8 semaines</span></td><td><span class=\"kw-clinique\">Rémission</span> symptomatique</td><td><strong>Épisode maniaque :</strong> <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">valproate</span> ou antipsychotique de 2ᵉ génération<br><strong>EDC bipolaire :</strong> <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">lamotrigine</span> ou <span class=\"kw-ttt\">quétiapine</span></td></tr>\n          <tr><td>Traitement de consolidation</td><td><span class=\"kw-chiffre\">4-6 mois</span></td><td>Prévention de la rechute, <span class=\"kw-clinique\">rémission</span> fonctionnelle</td><td>Idem si bonne tolérance ; anxiolytiques et hypnotiques arrêtés si possible</td></tr>\n          <tr><td>Traitement prophylactique</td><td><span class=\"kw-chiffre\">Long cours</span></td><td>Prévention des récurrences</td><td>Thymorégulateur adapté au patient, le plus souvent identique, avec adaptations posologiques possibles</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":2},{"id":"64-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement non pharmacologique au long cours","contenu":"<p><strong>Psychothérapies.</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Éducation thérapeutique</span> — excellente efficacité ; auto-<span class=\"kw-def\">surveillance</span>, repérage des signes de rechute, régularité des rythmes de vie</li>\n        <li><span class=\"kw-clinique\">Psychothérapie de soutien</span> — toujours indiquée, s'associe au traitement <span class=\"kw-etio\">médicamenteux</span> sans s'y substituer</li>\n        <li><span class=\"kw-clinique\">TCC et thérapies interpersonnelles</span> — niveaux de preuve <span class=\"kw-clinique\">les</span> plus élevés</li>\n        <li><span class=\"kw-clinique\">Remédiation cognitive</span> — destinée à pallier <span class=\"kw-clinique\">les</span> troubles cognitifs (présents chez <span class=\"kw-chiffre\">1/3</span> des patients) ; bilan neuropsychologique préalable requis</li>\n      </ul>\n      <p><strong>Électroconvulsivothérapie (ECT / sismothérapie).</strong> Traitement <span class=\"kw-clinique\">curatif</span>, recommandé lorsqu'une amélioration rapide est indispensable (<span class=\"kw-alerte\">pronostic vital engagé</span>) et <strong>après échec des autres options thérapeutiques</strong>. Indications principales :</p>\n      <ul>\n        <li>EDC <span class=\"kw-clinique\">sévère</span>, et/ou avec caractéristiques <span class=\"kw-clinique\">mélancoliques</span>, et/ou <span class=\"kw-clinique\">résistant</span></li>\n        <li>Épisode maniaque <span class=\"kw-clinique\">sévère et prolongé</span>, et/ou résistant</li>\n        <li>Syndrome catatonique ; <span class=\"kw-def\">trouble bipolaire</span> à <span class=\"kw-clinique\">cycles rapides</span></li>\n        <li>Mauvaise tolérance ou <span class=\"kw-ci\">contre-indication aux psychotropes</span> (femme enceinte, personne âgée)</li>\n      </ul>\n      <p>Sa seule <span class=\"kw-ci\">contre-indication absolue</span> est l'<span class=\"kw-ci\">HTIC</span> ; ses effets indésirables principaux sont la <span class=\"kw-clinique\">confusion</span> et des troubles mnésiques antérogrades, résolutifs en <span class=\"kw-chiffre\">~2 mois</span>.</p>\n      <p><strong>Prise en charge psycho-sociale.</strong> Réadaptation et réinsertion psychosociale chez <span class=\"kw-clinique\">les</span> patients présentant un handicap.</p>\n      <div class=\"callout callout-warn\"><strong>Niveau d'exigence.</strong> Le focus détaillé sur l'électroconvulsivothérapie est indiqué comme <strong>non exigible à l'ECN</strong> selon le Collège de psychiatrie — en connaître <span class=\"kw-clinique\">les</span> grandes indications suffit.</div>","frequence":2},{"id":"64-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des comorbidités non psychiatriques des patients souffrant de troubles bipolaires, le rôle du médecin généraliste","contenu":"<p><span class=\"kw-clinique\">Les</span> patients souffrant d'un <span class=\"kw-def\">trouble bipolaire</span> présentent fréquemment des <span class=\"kw-def\">pathologies non psychiatriques associées</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Maladies cardiovasculaires</span></li>\n        <li><span class=\"kw-clinique\">Syndrome métabolique</span></li>\n        <li><span class=\"kw-etio\">SAHOS</span></li>\n        <li>Pathologies <span class=\"kw-clinique\">endocriniennes</span>, tumorales, neurodégénératives, inflammatoires chroniques</li>\n      </ul>\n      <p>Ces <span class=\"kw-def\">comorbidités</span> sont en partie favorisées par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">effets indésirables des traitements</span> (notamment les antipsychotiques) et participent à la <span class=\"kw-alerte\">surmortalité</span>, principalement cardiovasculaire. Le <strong>médecin généraliste</strong> a un rôle central de <span class=\"kw-clinique\">dépistage et de suivi</span> de ces comorbidités somatiques et de <span class=\"kw-def\">surveillance</span> de la tolérance du traitement.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources de l'item sont peu détaillées sur le rôle précis du médecin généraliste ; ce paragraphe pourra être enrichi (Collège de psychiatrie / recommandations HAS).</div>","frequence":0}],"astuces":[{"type":"tip","titre":"Mnémo « QORA » — antipsychotiques 2ᵉ génération de la manie","contenu":"<p><strong>Q</strong>uétiapine · <strong>O</strong>lanzapine · <strong>R</strong>ispéridone · <strong>A</strong>ripiprazole. Utilisés seuls ou en association à un <span class=\"kw-ttt\">thymorégulateur</span> dans l'<span class=\"kw-clinique\">épisode maniaque</span> ; la <strong><span class=\"kw-ttt\">quétiapine</span></strong> a aussi l'AMM dans l'<span class=\"kw-def\">EDC</span> <span class=\"kw-clinique\">bipolaire</span> en <span class=\"kw-ttt\">monothérapie</span>.</p>"},{"type":"warn","titre":"Jamais d'antidépresseur en monothérapie chez un bipolaire","contenu":"<p>L'introduction d'un <span class=\"kw-ttt\">AD</span> seul expose à : <span class=\"kw-alerte\">virage maniaque</span>, <span class=\"kw-alerte\">accélération des cycles</span>, <span class=\"kw-alerte\">rechutes plus fréquentes</span>. Toujours associer un <span class=\"kw-ttt\">thymorégulateur</span>, et l'arrêter d'emblée en cas de <span class=\"kw-alerte\">virage maniaque</span>. Le <strong><span class=\"kw-ttt\">lithium</span></strong> reste la référence prophylactique (et le seul à avoir démontré un effet anti-suicide).</p>"},{"type":"tip","titre":"Repérer une dépression bipolaire — drapeaux cliniques","contenu":"<p>Évoquer la <span class=\"kw-clinique\">bipolarité</span> devant un <span class=\"kw-def\">EDC</span> avec : <strong>début &lt; <span class=\"kw-chiffre\">25 ans</span></strong> · épisodes <strong>brefs et répétés</strong> · <strong>hypersomnie + hyperphagie</strong> (forme atypique) · <strong><span class=\"kw-clinique\">ralentissement psychomoteur</span> majeur</strong> · caractéristiques <strong><span class=\"kw-clinique\">psychotiques</span>/mélancoliques</strong> · <strong>ATCD familiaux de <span class=\"kw-clinique\">bipolarité</span></strong> · <strong>virage <span class=\"kw-clinique\">hypomaniaque</span> sous <span class=\"kw-ttt\">AD</span></strong> · post-partum. Conséquence pratique : on ne démarre pas un <span class=\"kw-ttt\">AD</span> sans rechercher activement ces signes.</p>"},{"type":"warn","titre":"Caractéristique mixte = risque suicidaire majeur","contenu":"<p>L'association de symptômes maniaques et dépressifs au sein du même épisode (ex. <span class=\"kw-clinique\">agitation</span> + idées noires + <span class=\"kw-clinique\">culpabilité</span>) majore drastiquement le <span class=\"kw-alerte\">risque de <span class=\"kw-clinique\">passage à l'acte</span> <span class=\"kw-alerte\">suicidaire</span></span>. À identifier impérativement : changement de prise en charge (<span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-ttt\">valproate</span>/<span class=\"kw-ttt\">lithium</span> ± <span class=\"kw-ttt\">AP2G</span>, jamais d'<span class=\"kw-ttt\">AD</span> seul).</p>"},{"type":"tip","titre":"Lithium : surveillance pratique","contenu":"<p>Cible <strong><span class=\"kw-chiffre\">0,6-0,8 mmol/L</span></strong> en prophylaxie (0,8-1,2 en aigu). Lithémie à <strong>J5-<span class=\"kw-chiffre\">J7</span></strong> de toute modification, prélèvement <strong><span class=\"kw-chiffre\">12 h</span> après la dernière prise</strong>, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span>. <span class=\"kw-def\">Surveillance</span> : <span class=\"kw-bio\">créatinine</span>/<span class=\"kw-bio\">DFG</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">calcémie</span>, poids, <span class=\"kw-imagerie\">ECG</span>. Risque : néphropathie tubulo-interstitielle, <span class=\"kw-etio\">hypothyroïdie</span>, hyperparathyroïdie, <span class=\"kw-alerte\">tératogène</span> (Ebstein). Toxicité &gt; <span class=\"kw-chiffre\">1,2 mmol/L</span> : tremblements, <span class=\"kw-clinique\">confusion</span>, troubles digestifs.</p>"},{"type":"info","titre":"Chiffres clés à retenir","contenu":"<p><span class=\"kw-def\">Prévalence</span> <strong><span class=\"kw-chiffre\">1-4 %</span></strong> en population générale · héritabilité <strong><span class=\"kw-chiffre\">60-70 %</span></strong> · début <strong><span class=\"kw-chiffre\">15-25 ans</span></strong> · <span class=\"kw-alerte\">récidive</span> <strong><span class=\"kw-chiffre\">70-80 %</span></strong> à <span class=\"kw-chiffre\">2 ans</span> après un épisode · <strong>&gt;<span class=\"kw-chiffre\"> 90 %</span></strong> de <span class=\"kw-alerte\">récidive</span> après une 1<sup>re</sup> <span class=\"kw-clinique\">manie</span> · cycles rapides <strong><span class=\"kw-chiffre\">25 %</span></strong> · symptômes <span class=\"kw-clinique\">psychotiques</span> dans <strong><span class=\"kw-chiffre\">40-50 %</span></strong> des manies · <span class=\"kw-alerte\">suicide</span> <strong><span class=\"kw-chiffre\">15 %</span></strong> de <span class=\"kw-alerte\">mortalité</span> · espérance de vie réduite de <strong><span class=\"kw-chiffre\">10-20 ans</span></strong>.</p>"},{"type":"tip","titre":"Type 1 vs Type 2 — la nuance qui compte","contenu":"<p><strong>Type 1</strong> = au moins un épisode <strong>maniaque</strong> (<span class=\"kw-def\">EDC</span> non requis pour le diagnostic). <strong>Type 2</strong> = au moins un épisode <strong><span class=\"kw-clinique\">hypomaniaque</span></strong> + au moins un <strong><span class=\"kw-def\">EDC</span></strong>, et <strong>jamais</strong> d'<span class=\"kw-clinique\">épisode maniaque</span>. Le type 2 est à prédominance féminine et souvent sous-diagnostiqué (<span class=\"kw-clinique\">les</span> patients consultent pour leurs <span class=\"kw-def\">EDC</span>, pas leurs hypomanies vécues comme « bons moments »).</p>"}],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> l'<span class=\"kw-def\">épisode maniaque</span> est une <span class=\"kw-alerte\">urgence médicale</span> diagnostique et thérapeutique.<br><strong>Fenêtre diagnostique :</strong> le diagnostic d'épisode maniaque peut être posé dès qu'une <span class=\"kw-alerte\">hospitalisation</span> est nécessaire, sans attendre <span class=\"kw-chiffre\">≥ 1 semaine</span>.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">traitement symptomatique</span> (agitation, sommeil, réhydratation), <span class=\"kw-ttt\">arrêt de l'antidépresseur</span> si présent et mise en sécurité.</p>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> en psychiatrie, souvent en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-def\">épisode maniaque</span> (<span class=\"kw-alerte\">urgence médicale</span>).<br><strong>Hospitalisation :</strong> <span class=\"kw-def\">EDC</span> <span class=\"kw-alerte\">sévère</span> ou avec <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> (<span class=\"kw-alerte\">mélancolique</span>, <span class=\"kw-alerte\">psychotique</span>, <span class=\"kw-alerte\">mixte</span>, <span class=\"kw-alerte\">catatonique</span>).<br><strong>Hospitalisation :</strong> <span class=\"kw-alerte\">risque suicidaire élevé</span>, <span class=\"kw-alerte\">risque hétéro-agressif</span> ou complications médico-légales.<br><strong>Ambulatoire avec PEC rapide :</strong> <span class=\"kw-def\">épisode hypomaniaque</span> (pas d'hospitalisation en milieu spécialisé requise).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Caractéristiques mixtes</span> (symptômes maniaques et dépressifs simultanés) : <span class=\"kw-alerte\">risque suicidaire très augmenté</span></li><li><span class=\"kw-alerte\">Caractéristiques psychotiques</span> : idées délirantes, hallucinations</li><li><span class=\"kw-alerte\">Caractéristiques mélancoliques</span> ou <span class=\"kw-alerte\">catatoniques</span></li><li><span class=\"kw-alerte\">Risque suicidaire</span> : idées suicidaires avec plan précis</li><li><span class=\"kw-alerte\">Risque hétéro-agressif</span> et complications médico-légales</li><li><span class=\"kw-alerte\">Déshydratation</span> ou <span class=\"kw-alerte\">dénutrition</span> liées à l'agitation maniaque</li><li><span class=\"kw-etio\">Cycles rapides</span> (<span class=\"kw-chiffre\">≥ 4 épisodes</span> sur <span class=\"kw-chiffre\">12 mois</span>) : <span class=\"kw-def\">pronostic</span> plus sévère et résistance thérapeutique</li></ul>","principes":"<p>La PEC associe un <span class=\"kw-ttt\">traitement symptomatique</span>, un <span class=\"kw-ttt\">traitement de l'épisode aigu</span> selon sa polarité, puis un <span class=\"kw-ttt\">traitement au long cours</span> en 3 phases.</p><p><strong>Épisode maniaque — phase aiguë</strong></p><p>CAT : <span class=\"kw-alerte\">hospitalisation</span> en psychiatrie + traitement symptomatique (agitation, sommeil, hydratation)</p><ul><li><span class=\"kw-ttt\">Thymorégulateur</span> : <span class=\"kw-ttt\">lithium</span> en 1re intention (<span class=\"kw-ttt\">carbamazépine</span> ou <span class=\"kw-ttt\">valproate</span> si <span class=\"kw-ci\">inefficacité ou contre-indication</span>)</li><li><span class=\"kw-ttt\">Antipsychotique de 2e génération</span> : <span class=\"kw-ttt\">quétiapine</span>, <span class=\"kw-ttt\">olanzapine</span>, <span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">aripiprazole</span></li><li>Épisode sévère : <span class=\"kw-ttt\">association thymorégulateur + antipsychotique</span> possible</li><li><span class=\"kw-ttt\">Arrêt de l'antidépresseur</span> (risque de <span class=\"kw-alerte\">virage maniaque</span>)</li><li><span class=\"kw-ttt\">Sauvegarde de justice</span> si <span class=\"kw-clinique\">dépenses/achats excessifs</span> ; <span class=\"kw-ci\">pas de curatelle ni tutelle en urgence</span></li></ul><p><strong>EDC bipolaire — phase aiguë</strong></p><p>CAT : jamais d'<span class=\"kw-ttt\">antidépresseur</span> seul — risque de <span class=\"kw-alerte\">virage maniaque</span> et d'<span class=\"kw-alerte\">accélération des cycles</span></p><ul><li>1re intention en <span class=\"kw-ttt\">monothérapie</span> : <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">lamotrigine</span> ou <span class=\"kw-ttt\">quétiapine</span></li><li><span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-ttt\">ISRS</span> ajouté seulement si <span class=\"kw-ttt\">thymorégulateur</span> (<span class=\"kw-ttt\">lithium</span>/<span class=\"kw-ttt\">valproate</span>) déjà à dose efficace</li><li>Évaluation de la réponse après <span class=\"kw-chiffre\">≥ 2 semaines</span> à dose efficace</li></ul><p><strong>Traitement au long cours (3 phases)</strong></p><ul><li>Attaque <span class=\"kw-chiffre\">6-8 semaines</span> : <span class=\"kw-clinique\">rémission symptomatique</span></li><li>Consolidation <span class=\"kw-chiffre\">4-6 mois</span> : prévention de la <span class=\"kw-clinique\">rechute</span> et <span class=\"kw-clinique\">rémission</span> fonctionnelle</li><li>Prophylaxie <span class=\"kw-chiffre\">au long cours</span> : prévention des <span class=\"kw-clinique\">récurrences</span> par <span class=\"kw-ttt\">thymorégulateur</span></li></ul><p><strong>ECT (sismothérapie)</strong></p><ul><li>Indiquée si <span class=\"kw-alerte\">pronostic vital engagé</span> et <span class=\"kw-alerte\">après échec</span> des autres traitements</li><li><span class=\"kw-def\">EDC</span> sévère/mélancolique/résistant, <span class=\"kw-def\">manie</span> sévère et prolongée/résistante, <span class=\"kw-etio\">syndrome catatonique</span>, <span class=\"kw-etio\">cycles rapides</span></li><li><span class=\"kw-ci\">HTIC = seule contre-indication absolue</span></li></ul><p><strong>Mesures non pharmacologiques & sociales</strong></p><ul><li><span class=\"kw-ttt\">Éducation thérapeutique</span> (++) : repérage des signes de rechute, régularité des rythmes de vie</li><li><span class=\"kw-ttt\">Psychothérapie de soutien</span>, <span class=\"kw-ttt\">TCC</span>, <span class=\"kw-ttt\">remédiation cognitive</span> (troubles cognitifs chez <span class=\"kw-chiffre\">1/3</span> des patients)</li><li><span class=\"kw-ttt\">ALD 30 à 100 %</span> avec exonération du ticket modérateur</li></ul>","suivi":"<p><strong>Évaluation de la réponse :</strong> après <span class=\"kw-chiffre\">≥ 2 semaines</span> de traitement à dose efficace.<br><strong>Phases du traitement :</strong> attaque <span class=\"kw-chiffre\">6-8 semaines</span> → consolidation <span class=\"kw-chiffre\">4-6 mois</span> → prophylaxie au long cours.<br><strong>Risque de récidive :</strong> <span class=\"kw-chiffre\">70-80 %</span> des patients récidivent dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 ans</span> suivant un épisode ; surveiller le <span class=\"kw-alerte\">risque suicidaire</span> (<span class=\"kw-chiffre\">15 %</span> de décès par suicide).<br><strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-def\">dépistage</span> des <span class=\"kw-etio\">maladies cardiovasculaires</span>, du <span class=\"kw-etio\">syndrome métabolique</span> et des <span class=\"kw-etio\">troubles addictifs</span> (rôle du médecin généraliste).</p>"},"liensGlobaux":[{"href":"https://www.youtube.com/watch?v=uW4Yl447z1c","label":"YouTube — Vidéo trouble bipolaire"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Syndrome thymique aigu suspecté — Épisode maniaque, hypomaniaque ou dépressif","detail":"<h4>CAT — Trouble bipolaire : épisode thymique aigu — Du syndrome thymique à l'orientation thérapeutique</h4>","branches":[{"to":"q-org","label":"Bilan étiologique","color":"blue"}]},{"id":"q-org","kind":"decision","label":"Cause non-psychiatrique ou iatrogène retrouvée ? — Bilan : glycémie, ionogramme, calcémie, TSHus, toxiques urinaires, IRM si 1er épisode","branches":[{"to":"t-org","label":"Oui","color":"amber"},{"to":"q-type","label":"Non (origine psychiatrique)","color":"blue"}]},{"id":"t-org","kind":"terminal","label":"Traiter la cause / arrêt du médicament inducteur","color":"amber","detail":"<h4>Conduite</h4><ul><li>Arrêt des <span class=\"kw-etio\">médicaments inducteurs</span> : <span class=\"kw-etio\">corticoïdes</span>, <span class=\"kw-etio\">antidépresseurs</span>, <span class=\"kw-etio\">β-bloquants</span>, <span class=\"kw-etio\">L-DOPA</span>, <span class=\"kw-etio\">interféron α</span></li><li>Traitement de l'<span class=\"kw-etio\">affection causale</span> (dysthyroïdie, cause neurologique ou métabolique…)</li></ul><h4>Délai</h4><ul><li>Si <span class=\"kw-clinique\">les</span> symptômes <span class=\"kw-alerte\">persistent après l'arrêt</span> de la substance → suspecter un <span class=\"kw-def\">trouble bipolaire</span></li></ul>"},{"id":"q-type","kind":"decision","label":"Type d'épisode caractérisé actuel ? — Le diagnostic de trouble bipolaire requiert un épisode (hypo)maniaque","branches":[{"to":"t-manie","label":"Épisode maniaque","color":"red"},{"to":"t-hypo","label":"Épisode hypomaniaque","color":"amber"},{"to":"q-grav","label":"Épisode dépressif (EDC)","color":"blue"}]},{"id":"t-manie","kind":"terminal","label":"Hospitalisation en psychiatrie, en urgence","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-alerte\">Urgence médicale</span> : <span class=\"kw-alerte\">hospitalisation</span> le plus souvent en <span class=\"kw-alerte\">urgence</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thymorégulateur</span> : <span class=\"kw-ttt\">lithium</span> (ou <span class=\"kw-ttt\">carbamazépine</span>/<span class=\"kw-ttt\">valproate</span> si <span class=\"kw-ci\">CI ou inefficacité</span>)</li><li>et/ou <span class=\"kw-ttt\">antipsychotique de 2e génération</span> (<span class=\"kw-ttt\">quétiapine</span>, <span class=\"kw-ttt\">olanzapine</span>, <span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">aripiprazole</span>) ; association si sévère</li><li><span class=\"kw-ttt\">Arrêt de l'antidépresseur</span> ; <span class=\"kw-ttt\">ECT</span> si <span class=\"kw-alerte\">pronostic vital engagé</span> ou résistance</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> (agitation, sommeil, réhydratation)</li><li><span class=\"kw-ttt\">Sauvegarde de justice</span> si <span class=\"kw-clinique\">dépenses excessives</span> ; <span class=\"kw-ci\">pas de tutelle ni curatelle en urgence</span></li></ul>"},{"id":"t-hypo","kind":"terminal","label":"PEC ambulatoire rapide, sans hospitalisation spécialisée","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Épisode hypomaniaque</span> : symptomatologie et retentissement moindres, durée <span class=\"kw-chiffre\">≥ 4 jours</span></li></ul><h4>Conduite</h4><ul><li>Pas d'<span class=\"kw-alerte\">hospitalisation</span> en milieu spécialisé, mais <span class=\"kw-clinique\">PEC rapide</span> requise</li><li>Associé à un <span class=\"kw-def\">EDC</span>, confirme un <span class=\"kw-def\">trouble bipolaire de type II</span></li></ul>"},{"id":"q-grav","kind":"decision","label":"EDC sévère ou critères de gravité ? — Mélancolique, psychotique, mixte, catatonique ou risque suicidaire élevé","branches":[{"to":"t-edc-grave","label":"Oui","color":"red"},{"to":"t-edc-ambu","label":"Non","color":"green"}]},{"id":"t-edc-grave","kind":"terminal","label":"Hospitalisation","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">EDC sévère</span> ou <span class=\"kw-alerte\">caractéristiques mélancoliques / psychotiques / mixtes / catatoniques</span></li><li><span class=\"kw-alerte\">Risque suicidaire élevé</span> ou mise en danger</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Lithium</span>, <span class=\"kw-ttt\">lamotrigine</span> ou <span class=\"kw-ttt\">quétiapine</span> en monothérapie</li><li><span class=\"kw-ttt\">ECT</span> si <span class=\"kw-alerte\">pronostic vital engagé</span>, caractéristique mélancolique ou résistance</li></ul>"},{"id":"t-edc-ambu","kind":"terminal","label":"PEC ambulatoire — monothérapie","color":"green","detail":"<h4>Traitement</h4><ul><li>1re intention en <span class=\"kw-ttt\">monothérapie</span> : <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">lamotrigine</span> ou <span class=\"kw-ttt\">quétiapine</span></li><li><span class=\"kw-ttt\">ISRS</span> en <span class=\"kw-chiffre\">2e intention</span>, seulement si <span class=\"kw-ttt\">thymorégulateur</span> déjà à dose efficace</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Évaluation de la réponse après <span class=\"kw-chiffre\">≥ 2 semaines</span></li><li>Jamais d'<span class=\"kw-ttt\">antidépresseur</span> seul : risque de <span class=\"kw-alerte\">virage maniaque</span></li></ul>"}]},"cards":[{"i":"0b584e323c62","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Comment définit-on globalement un épisode maniaque chez l'adulte ou l'adolescent?","a":"<p>Un épisode maniaque se caractérise par une <strong>augmentation pathologique de l'humeur et de l'énergie ou de l'activité</strong>, persistant dans le temps (généralement <strong>≥ 1 semaine</strong>).</p>"},{"i":"0ea3992b9ffa","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Un épisode maniaque survenant sous antidépresseur doit-il toujours exclure le diagnostic de trouble bipolaire ?","a":"<p>Non. Un épisode maniaque complet apparu au cours d'un traitement antidépresseur (ou électroconvulsivothérapie) doit être considéré comme tel s'il <strong>persiste au-delà de l'effet physiologique de ce traitement</strong>. Il conduit alors au diagnostic de trouble bipolaire.</p>"},{"i":"2c094d9bfec1","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Quel est l'impact fonctionnel nécessaire pour diagnostiquer un épisode maniaque ?","a":"<p>Il doit y avoir une <strong>altération marquée du fonctionnement</strong> professionnel ou social, ou la nécessité d'une hospitalisation, ou la présence de caractéristiques psychotiques.</p>"},{"i":"7a37a34ffd10","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Quelles sont les composantes cliniques principales du tableau d'un épisode maniaque ?","a":"<p>Le tableau clinique d'un épisode maniaque se décline en <strong>trois composantes</strong> :</p><ul><li>Psychoaffective</li><li>Psychomotrice</li><li>Physiologique</li></ul>"},{"i":"9b812b23dc12","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Quels sont les symptômes secondaires à rechercher selon le DSM-5 pour le diagnostic d'un épisode maniaque ?","a":"<p>Il faut retrouver <strong>au moins 3 symptômes</strong> parmi les suivants (ou 4 si l'humeur est seulement irritable) :</p><ul><li>Augmentation de l'estime de soi / idées de grandeur</li><li><strong>Réduction du besoin de sommeil</strong></li><li>Communicabilité accrue</li><li><strong>Fuite des idées</strong></li><li>Distractibilité</li><li>Augmentation de l'activité orientée vers un but ou agitation psychomotrice</li><li>Engagement excessif dans des activités à risque</li></ul>"},{"i":"d905d5958ede","n":64,"o":"64-1","u":"Définition","t":"Connaître la définition d’un épisode maniaque","q":"Selon les critères diagnostiques, quels sont les signes caractéristiques de l'humeur et de l'énergie observables lors d'un épisode maniaque ?","a":"<p>Il s'agit d'une période nettement délimitée d'<strong>humeur élevée, expansive ou irritable</strong> de façon anormale, accompagnée d'une <strong>augmentation anormale de l'énergie ou de l'activité</strong> orientée vers un but. Ces symptômes doivent être présents presque tous les jours, pendant <strong>≥ 1 semaine</strong>, ou de toute durée si une hospitalisation est nécessaire.</p>"},{"i":"0a5a19577078","n":64,"o":"64-10","u":"Diagnostic positif","t":"Connaître les caractéristiques évocatrices d’une dépression bipolaire","q":"Quels sont les éléments du terrain qui doivent faire évoquer une dépression bipolaire ?","a":"<p>Devant un épisode dépressif, les éléments de terrain qui doivent faire évoquer un trouble bipolaire sont :</p><ul><li>Des <strong>antécédents familiaux de trouble de l'humeur</strong>.</li><li>Un épisode dépressif caractérisé avant l'âge de <strong>25 ans</strong>.</li></ul>"},{"i":"5783f63ab6c5","n":64,"o":"64-10","u":"Diagnostic positif","t":"Connaître les caractéristiques évocatrices d’une dépression bipolaire","q":"Dans quel contexte un épisode dépressif doit-il faire évoquer une dépression bipolaire ?","a":"<p>Un épisode dépressif doit faire évoquer une dépression bipolaire dans les contextes suivants :</p><ul><li>Épisode dépressif caractérisé (EDC) survenant en <strong>post-partum</strong>.</li><li><strong>Antécédents d'épisodes dépressifs caractérisés multiples</strong> (<strong>≥ 3</strong>).</li></ul>"},{"i":"750891bdc945","n":64,"o":"64-10","u":"Diagnostic positif","t":"Connaître les caractéristiques évocatrices d’une dépression bipolaire","q":"Comment la réponse au traitement antidépresseur peut-elle faire suspecter une dépression bipolaire ?","a":"<p>La réponse au traitement antidépresseur peut faire suspecter une dépression bipolaire si elle est <strong>inadéquate</strong>, notamment :</p><ul><li>Une <strong>non-réponse</strong> ou une <strong>aggravation</strong> des symptômes sous antidépresseur seul.</li><li>L'apparition d'une <strong>agitation</strong>.</li><li>L'apparition d'une <strong>hypomanie</strong>, même brève.</li><li>Le risque est l'induction d'un <strong>virage maniaque</strong> si un antidépresseur est prescrit seul.</p></ul>"},{"i":"a585ab5211cb","n":64,"o":"64-10","u":"Diagnostic positif","t":"Connaître les caractéristiques évocatrices d’une dépression bipolaire","q":"Quelles sont les caractéristiques de l'épisode dépressif lui-même qui sont évocatrices d'une dépression bipolaire ?","a":"<p>Les caractéristiques cliniques de l'épisode dépressif qui peuvent faire évoquer un trouble bipolaire sont :</p><ul><li>Un <strong>début brutal</strong> de l'épisode dépressif caractérisé.</li><li>Des caractéristiques cliniques <strong>mélancoliques</strong>.</li><li>Un caractère <strong>saisonnier</strong> de la dépression.</li></ul>"},{"i":"544dba3326fc","n":64,"o":"64-12","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelles sont les différentes phases du traitement du trouble bipolaire et leurs objectifs respectifs ?","a":"Le traitement du trouble bipolaire se décompose en trois phases :\n<ul>\n<li>Le <strong>traitement d'attaque</strong> (6-8 semaines) : Vise la <strong>rémission symptomatique</strong>.</li>\n<li>Le <strong>traitement de consolidation</strong> (4-6 mois) : Vise la <strong>prévention de la rechute</strong> et la rémission fonctionnelle.</li>\n<li>Le <strong>traitement prophylactique</strong> (au long cours) : Vise la <strong>prévention des récurrences</strong>.</li>\n</ul>"},{"i":"58944d4cb475","n":64,"o":"64-12","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelle prise en charge sociale et juridique peut être proposée à un patient souffrant de trouble bipolaire ?","a":"Sur le plan social et juridique, plusieurs dispositifs existent :\n<ul>\n<li>Le trouble bipolaire peut être reconnu en <strong>ALD 30 à 100 %</strong> avec une exonération du ticket modérateur.</li>\n<li>Une <strong>réadaptation psychosociale</strong> peut être envisagée en cas de handicap.</li>\n<li>En cas de dépenses ou d'achats excessifs, une <strong>sauvegarde de justice</strong> peut être mise en place comme mesure de protection juridique. Il n'y a pas d'urgence pour la curatelle ou la tutelle.</li>\n</ul>"},{"i":"733a819e7322","n":64,"o":"64-12","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quels sont les différents types de psychothérapies recommandés dans la prise en charge du trouble bipolaire ?","a":"Plusieurs types de psychothérapies sont complémentaires à la prise en charge médicamenteuse :\n<ul>\n<li>L'<strong>éducation thérapeutique</strong> : Très efficace pour la compréhension du trouble, le repérage des signes précurseurs et la régularité des rythmes de vie.</li>\n<li>La <strong>psychothérapie de soutien</strong> : Toujours indiquée, elle est complémentaire mais ne remplace pas le traitement médicamenteux.</li>\n<li>Les <strong>TCC (Thérapies Cognitivo-Comportementales) et les thérapies interpersonnelles</strong> : Elles ont les niveaux de preuve les plus élevés.</li>\n<li>La <strong>remédiation cognitive</strong> : Utilisée pour les troubles cognitifs (présents chez 1/3 des patients), elle est précédée d'un bilan neuropsychologique.</li>\n</ul>"},{"i":"891bfc34ba8e","n":64,"o":"64-12","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Quelles sont les indications justifiant une hospitalisation en psychiatrie chez un patient présentant un trouble bipolaire ?","a":"Les indications justifiant une hospitalisation sont :\n<ul>\n<li>Un <strong>épisode maniaque</strong>, qui est une urgence médicale nécessitant le plus souvent une hospitalisation en urgence.</li>\n<li>Un <strong>épisode dépressif caractérisé sévère</strong>, ou avec des critères de gravité (caractéristique mélancolique, psychotique, mixte, catatonique).</li>\n<li>Un <strong>risque suicidaire élevé</strong> ou un risque de mise en danger.</li>\n<li>Des <strong>perturbations importantes du comportement</strong> ayant des conséquences délétères potentielles.</li>\n<li>Un <strong>risque hétéro-agressif</strong> ou des complications médico-légales.</li>\n</ul>"},{"i":"0fb020a8c439","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quelle est la monothérapie de première ligne pour un épisode dépressif caractérisé (EDC) du trouble bipolaire ?","a":"<p>La monothérapie de première ligne peut être le <strong>lithium</strong>, la <strong>lamotrigine</strong>, ou la <strong>quétiapine</strong>.</p>"},{"i":"24cb14cecd87","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quelle est la règle essentielle concernant la prescription d'un antidépresseur chez un patient bipolaire ?","a":"<p>Un antidépresseur ne doit <strong>jamais être prescrit seul</strong> ; il doit toujours être associé à un <strong>thymorégulateur</strong>.</p>"},{"i":"4560d9fee163","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quels sont les traitements pharmacologiques du trouble bipolaire en cas de contre-indication ou d'inefficacité du lithium face à un épisode maniaque ?","a":"<p>Si le lithium est contre-indiqué ou inefficace, la <strong>carbamazépine</strong> ou le <strong>valproate</strong> peuvent être utilisés.</p>"},{"i":"7653620e2e9b","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quels sont les risques liés à l'utilisation d'antidépresseurs chez un patient atteint de trouble bipolaire ?","a":"<ul><li>Risque de <strong>virage maniaque</strong> (effet aigu).</li><li>Au long cours, favorise les <strong>rechutes</strong> et l'<strong>accélération des cycles</strong>.</li></ul>"},{"i":"7ca214100fb7","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quel est le traitement pharmacologique de première intention d'un épisode maniaque du trouble bipolaire ?","a":"<p>En première intention, le traitement est un <strong>thymorégulateur (lithium)</strong> et/ou un <strong>antipsychotique de 2ᵉ génération</strong>, notamment la <strong>quétiapine</strong>, l'<strong>olanzapine</strong>, la <strong>rispéridone</strong> ou l'<strong>aripiprazole</strong>.</p>"},{"i":"b7affeb5362f","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quelle mesure faut-il prendre concernant un antidépresseur si un patient bipolaire présente un épisode maniaque ?","a":"<p>Il est impératif d'<strong>arrêter l'antidépresseur</strong> s'il est en cours de traitement.</p>"},{"i":"dfeaecc9e0f7","n":64,"o":"64-13","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique des épisodes aigus","q":"Quelle est la stratégie de traitement de deuxième ligne pour un épisode dépressif caractérisé (EDC) du trouble bipolaire si un thymorégulateur est déjà en place ?","a":"<p>Si un thymorégulateur (<strong>lithium</strong> ou <strong>valproate</strong>) est déjà en place et efficace, l'ajout d'un <strong>antidépresseur ISRS</strong> est possible.</p>"},{"i":"6b33db6c69e4","n":64,"o":"64-2","u":"Définition","t":"Connaître la définition d’un épisode hypomaniaque","q":"Comment évaluer l'intensité et le retentissement fonctionnel d'un épisode hypomaniaque par rapport à un épisode maniaque ?","a":"<p>L'épisode hypomaniaque présente une symptomatologie et un retentissement fonctionnel <strong>moins importants</strong> que l'épisode maniaque. Il y a une rupture totale avec l'état antérieur, souvent constatée par l'entourage, mais sans altération marquée du fonctionnement nécessitant une hospitalisation.</p>"},{"i":"a92e152d4ea9","n":64,"o":"64-2","u":"Définition","t":"Connaître la définition d’un épisode hypomaniaque","q":"La présence de caractéristiques psychotiques est-elle compatible avec le diagnostic d'épisode hypomaniaque ?","a":"<p>Non, la présence de caractéristiques psychotiques est <strong>incompatible</strong> avec le diagnostic d'épisode hypomaniaque. Leur présence reclasse l'épisode en <strong>maniaque</strong>. Il s'agit d'un piège diagnostic classique.</p>"},{"i":"f715ab6ee2fb","n":64,"o":"64-2","u":"Définition","t":"Connaître la définition d’un épisode hypomaniaque","q":"Quelle est la durée minimale d'un épisode hypomaniaque selon les critères diagnostiques ?","a":"<p>Un épisode hypomaniaque doit durer au moins <strong>4 jours consécutifs</strong>.</p>"},{"i":"16f851bfe5e5","n":64,"o":"64-3","u":"Définition","t":"Connaître la définition d’un épisode dépressif bipolaire","q":"Selon le critère A du DSM-5, quels sont les symptômes clés et la durée requise pour un épisode dépressif caractérisé ?","a":"<p>Il doit y avoir présence d'au moins <strong>5 symptômes sur 9</strong>, pendant une même période de <strong>2 semaines</strong>, représentant un changement par rapport à l'état antérieur. Parmi ces symptômes, au moins un doit être une <strong>humeur dépressive</strong> ou une <strong>perte d'intérêt ou de plaisir</strong>.</p>"},{"i":"30333119c217","n":64,"o":"64-3","u":"Définition","t":"Connaître la définition d’un épisode dépressif bipolaire","q":"Comment définit-on un épisode dépressif bipolaire ?","a":"<p>Un épisode dépressif bipolaire correspond à un <strong>épisode dépressif caractérisé (EDC)</strong> qui survient dans le cadre d'un <strong>trouble bipolaire</strong>. Ses critères diagnostiques sont <strong>identiques</strong> à ceux de l'EDC unipolaire.</p>"},{"i":"4fb026a5d7eb","n":64,"o":"64-3","u":"Définition","t":"Connaître la définition d’un épisode dépressif bipolaire","q":"Quelles sont les 4 conditions essentielles pour poser le diagnostic d'un épisode dépressif caractérisé (EDC) ?","a":"<ul><li>La présence d'un <strong>syndrome dépressif</strong> (humeur triste et baisse d'énergie).</li><li>Une évolution depuis au moins <strong>15 jours</strong>.</li><li>Une <strong>altération marquée</strong> du fonctionnement professionnel, social, ou relationnel.</li><li>L'<strong>absence de diagnostic différentiel</strong>.</li></ul>"},{"i":"f09aaf013c12","n":64,"o":"64-3","u":"Définition","t":"Connaître la définition d’un épisode dépressif bipolaire","q":"Quels sont les 9 symptômes du critère A du DSM-5 pour un épisode dépressif caractérisé ?","a":"<ul><li><strong>Humeur dépressive</strong> présente quasiment toute la journée, presque tous les jours.</li><li><strong>Diminution marquée de l'intérêt ou du plaisir</strong> pour presque toutes les activités.</li><li><strong>Perte ou gain de poids significatif</strong>, ou modification de l'appétit.</li><li><strong>Insomnie ou hypersomnie</strong> presque tous les jours.</li><li><strong>Agitation ou ralentissement psychomoteur</strong>.</li><li><strong>Fatigue ou perte d'énergie</strong>.</li><li><strong>Sentiment de dévalorisation</strong> ou de culpabilité excessive.</li><li><strong>Diminution de l'aptitude à penser / se concentrer</strong>, ou indécision.</li><li><strong>Pensées de mort récurrentes</strong>, idées suicidaires (avec ou sans plan).</li></ul>"},{"i":"8aae7a2a0e43","n":64,"o":"64-5","u":"Epidémiologie","t":"Connaître la prévalence","q":"Quelle est la prévalence des troubles bipolaires de type I ou II dans la population générale ?","a":"<p>La prévalence des troubles bipolaires de type I ou II dans la population générale est de <strong>1 à 4 %</strong>.</p>"},{"i":"bfb49f77267f","n":64,"o":"64-5","u":"Epidémiologie","t":"Connaître la prévalence","q":"Quelle est la prévalence des troubles bipolaires chez l'enfant et l'adolescent ?","a":"<ul><li>Chez l'<strong>enfant</strong>, la prévalence est <strong>rare</strong>, environ <strong>0,1 %</strong>.</li><li>Chez l'<strong>adolescent</strong>, la prévalence est <strong>plus fréquente</strong>, supérieure à <strong>1 %</strong>.</li></ul>"},{"i":"25d9b5eb35fc","n":64,"o":"64-8","u":"Diagnostic positif","t":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","q":"Quelles sont les spécificités du syndrome hypomaniaque par rapport au syndrome maniaque chez l'adulte ?","a":"<p>Le syndrome hypomaniaque présente des manifestations similaires au syndrome maniaque, mais de <strong>moindre intensité</strong>. Il dure au moins <strong>4 jours consécutifs</strong>, entraîne un <strong>retentissement fonctionnel moindre</strong> et <strong>ne nécessite pas d'hospitalisation</strong>.</p>"},{"i":"526d45fbcf04","n":64,"o":"64-8","u":"Diagnostic positif","t":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","q":"Quelles sont les perturbations physiologiques observées dans un syndrome maniaque chez l'adulte ?","a":"<ul><li><strong>Insomnie</strong> avec réduction du temps de sommeil sans sensation de fatigue.</li><li><strong>Augmentation du désir et de l'excitation sexuelle</strong> (hypersexualité).</li><li><strong>Anorexie</strong> ou hyperphagie pouvant entraîner amaigrissement et déshydratation.</li></ul>"},{"i":"566a505d6762","n":64,"o":"64-8","u":"Diagnostic positif","t":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","q":"Quelle est la particularité diagnostique du syndrome maniaque ou hypomaniaque chez l'enfant et l'adolescent ?","a":"<p>Le diagnostic est difficile. On s'appuie principalement sur l'<strong>irritabilité</strong>, voire l'<strong>agressivité</strong>, comme manifestation principale.</p>"},{"i":"65d82795824b","n":64,"o":"64-8","u":"Diagnostic positif","t":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","q":"Quelles sont les perturbations psychomotrices principales observées dans un syndrome maniaque chez l'adulte ?","a":"<ul><li><strong>Tachypsychie</strong>, <strong>fuite des idées</strong>, coq-à-l'âne.</li><li><strong>Agitation</strong>, <strong>hyperactivité</strong> (souvent stérile).</li><li><strong>Logorrhée</strong>, <strong>tachyphémie</strong>, <strong>hypermimie</strong>.</li><li><strong>Désinhibition</strong>.</li></ul>"},{"i":"d92642d9edcf","n":64,"o":"64-8","u":"Diagnostic positif","t":"Connaître la sémiologie des syndromes maniaque et hypomaniaque","q":"Comment se caractérise l'humeur dans un syndrome maniaque chez l'adulte ?","a":"<p>L'humeur est classiquement <strong>élevée</strong>, <strong>expansive</strong>, <strong>exaltée</strong>, voire <strong>euphorique</strong>. Elle peut être également marquée par une <strong>irritabilité</strong>.</p>"},{"i":"0518508786c4","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Comment le syndrome dépressif peut-il se présenter spécifiquement chez la personne âgée ?","a":"<p>Chez la personne âgée, le syndrome dépressif peut se manifester par des <strong>plaintes d'allure non psychiatrique</strong>, souvent <strong>algiques</strong> (douleurs), ou des <strong>plaintes mnésiques</strong> (troubles de la mémoire).</p>"},{"i":"3830c2043b6c","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Quelles sont les spécificités du syndrome dépressif chez l'enfant et l'adolescent ?","a":"<p>Chez l'enfant et l'adolescent, la tristesse peut se manifester par des <strong>crises de colère</strong> ou de l'<strong>irritabilité</strong>. On peut également observer une altération du rendement scolaire. Un premier épisode précoce est associé à un risque plus élevé de récidive et de risque suicidaire.</p>"},{"i":"af2a8c3f4c71","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Quelles sont les perturbations physiologiques associées au syndrome dépressif ?","a":"<ul><li><strong>Troubles du sommeil</strong> (insomnie avec réveils nocturnes/précoces, difficultés d'endormissement, ou somnolence).</li><li><strong>Fatigue</strong> et <strong>asthénie</strong> (signe d'appel fréquent mais non spécifique).</li><li><strong>Anorexie</strong> (le plus fréquent) ou augmentation de l'appétit, avec variations de poids.</li><li><strong>Hyposexualité</strong> (diminution du désir et de l'excitation sexuelle).</li></ul>"},{"i":"b2f46d6b5c5d","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Quelles sont les perturbations psychoaffectives principales du syndrome dépressif ?","a":"<ul><li><strong>Humeur dépressive/triste</strong>, permanente, souvent prédominant le matin et s'améliorant en soirée.</li><li><strong>Anhédonie</strong> (perte du plaisir) et <strong>anesthésie affective</strong> (émoussement des émotions).</li><li>Anxiété et <strong>irritabilité</strong> (notamment chez l'adolescent).</li><li>Idées de <strong>culpabilité/auto-accusation</strong>, de <strong>dévalorisation</strong>, d'<strong>incurabilité</strong>.</li><li><strong>Pensées de mort</strong>, incluant des idées suicidaires.</li></ul>"},{"i":"ed287ee313f4","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Quelles sont les perturbations psychomotrices observables dans un syndrome dépressif ?","a":"<ul><li><strong>Bradypsychie</strong> (ralentissement du cours de la pensée), ruminations, monoïdéisme.</li><li>Altérations de la <strong>concentration, mémoire, attention</strong> et indécision.</li><li><strong>Ralentissement moteur</strong> (bradykinésie, hypomimie, bradyphémie, aprosodie, clinophilie, incurie, aboulie).</li><li>Possibilité d'<strong>agitation psychomotrice</strong> (déambulations permanentes liées à l'anxiété).</li></ul>"},{"i":"f6b4a486b130","n":64,"o":"64-9","u":"Diagnostic positif","t":"Connaître la sémiologie du syndrome dépressif","q":"Comment définir le syndrome dépressif et quelle est sa durée minimale pour le diagnostic ?","a":"<p>Le syndrome dépressif est caractérisé par la persistance d'une <strong>tristesse pathologique de l'humeur</strong> et une <strong>baisse d'énergie</strong>, pendant une durée d'au moins <strong>15 jours</strong>.</p>"}]};